<?php if ($tab === 'contributions'): ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const features=<?= json_encode($features, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const map=L.map('my-contributions-map').setView([47.531,-0.102],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const layer=L.geoJSON({type:'FeatureCollection',features}).addTo(map);if(features.length)map.fitBounds(layer.getBounds(),{padding:[16,16]});</script><?php endif; ?>
